import React, { useState, useEffect } from 'react';
import Navbar from './components/NavBar';
// Assuming Tailwind CSS is set up in your project
// Assuming you are using React Router for <Link /> components
// import { Link } from 'react-router-dom'; // Uncomment this if using React Router

// Placeholder function to simulate fetching download links
// In a real app, this would make an API call to your backend
const fetchDownloadOptions = async (url) => {
  console.log('Fetching options for:', url);
  // Simulate network delay
  await new Promise(resolve => setTimeout(resolve, 1500));

  // Basic URL validation
  if (!url || !url.trim()) {
      throw new Error('Please enter a Facebook video URL.');
  }
  // Simple check if it looks like a Facebook URL (can be improved)
   if (!url.includes('facebook.com')) {
       throw new Error('Please enter a valid Facebook URL.');
   }


  // Simulate success for a specific dummy URL pattern
  if (url.includes('facebook.com/watch/') || url.includes('facebook.com/videos/')) {
    // Simulate successful response with download options
    return [
      { quality: 'HD', url: '#', format: 'MP4', size: 'Approx. 50MB' }, // Replace '#' with actual download links
      { quality: 'SD', url: '#', format: 'MP4', size: 'Approx. 20MB' }, // Replace '#' with actual download links
    ];
  } else {
    // Simulate an error for other URLs
    throw new Error('Could not fetch video from this URL. Please check the URL or try again.');
  }
};


function App() { // Renamed back to App or keep HomePage, ensure default export matches
  // State to manage the input URL
  const [videoUrl, setVideoUrl] = useState('');
  // State to manage dark mode
  const [darkMode, setDarkMode] = useState(false);
  // State for loading status
  const [isLoading, setIsLoading] = useState(false);
  // State for error messages
  const [error, setError] = useState(null);
  // State for storing download options received from the API
  const [downloadOptions, setDownloadOptions] = useState([]); // Array<{quality, url, format, size}>

  // Effect to check local storage for dark mode preference on mount
  useEffect(() => {
    const isDarkMode = localStorage.getItem('darkMode') === 'true';
    setDarkMode(isDarkMode);
    // Apply dark mode class to the body or html element
    if (isDarkMode) {
      document.documentElement.classList.add('dark');
    } else {
      document.documentElement.classList.remove('dark');
    }
  }, []); // Empty dependency array means this effect runs only once on mount

  // Function to handle dark mode toggle
  const toggleDarkMode = () => {
    const newDarkMode = !darkMode;
    setDarkMode(newDarkMode);
    // Save preference to local storage
    localStorage.setItem('darkMode', newDarkMode);
    // Apply/remove dark mode class
    if (newDarkMode) {
      document.documentElement.classList.add('dark');
    } else {
      document.documentElement.classList.remove('dark');
    }
  };

  // Function to handle input change
  const handleInputChange = (event) => {
    setVideoUrl(event.target.value);
     // Clear error and options when user starts typing again
    if (error) {
        setError(null);
    }
    if (downloadOptions.length > 0) {
        setDownloadOptions([]);
    }
  };

  // Function to handle download button click (uses the logic from your snippet)
  const handleDownload = async () => {
    setError(null); // Clear previous errors
    setDownloadOptions([]); // Clear previous results
    setIsLoading(true);

    try {
      // Call the placeholder function (replace with actual API call)
      const options = await fetchDownloadOptions(videoUrl);
      setDownloadOptions(options);
    } catch (err) {
      setError(err.message || 'An unexpected error occurred.');
      setDownloadOptions([]); // Ensure no stale options are shown on error
    } finally {
      setIsLoading(false);
    }
  };

  // Placeholder Link component if React Router is not set up
  // Replace with actual Link import if using React Router
  const Link = ({ to, children, ...props }) => <a href={to} {...props}>{children}</a>;


  return (
    // Main container applying dark mode class based on state
    // Using gray tones for dark mode background and text
    <div className={`min-h-screen bg-gray-100 dark:bg-gray-800 text-gray-900 dark:text-gray-200 flex flex-col items-center transition-colors duration-300`}>
      <Navbar/>

      {/* Navigation Bar */}
      <nav className="w-full bg-white dark:bg-gray-900 shadow-md dark:shadow-lg p-4 flex justify-between items-center">
        {/* Site Title/Logo - Use Link to home */}
        <Link to="/" className="text-xl font-bold text-blue-600 dark:text-blue-400 hover:text-blue-800 dark:hover:text-blue-300 transition-colors duration-200">
          FB Downloader
        </Link>

        {/* Nav Links */}
        <div className="flex items-center space-x-4">
          {/* Dark Mode Toggle */}
          <button
            onClick={toggleDarkMode}
            className="p-2 rounded-full bg-gray-200 dark:bg-gray-700 text-gray-700 dark:text-gray-200 focus:outline-none focus:ring-2 focus:ring-blue-500 dark:focus:ring-blue-400 transition-colors duration-300"
            aria-label="Toggle Dark Mode"
          >
            {/* Simple icon representation (Sun for Light, Moon for Dark) */}
            {darkMode ? (
               // Sun icon for Dark Mode
              <svg xmlns="http://www.w3.org/2000/svg" className="h-6 w-6" fill="none" viewBox="0 0 24 24" stroke="currentColor">
                <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M12 3v1m0 16v1m9-9h-1M4 12H3m15.364 6.364l-.707-.707M6.343 6.343l-.707-.707m12.728 0l-.707.707M6.343 17.657l-.707.707M16 12a4 4 0 11-8 0 4 4 0 018 0z" />
              </svg>
            ) : (
              // Moon icon for Light Mode
              <svg xmlns="http://www.w3.org/2000/svg" className="h-6 w-6" fill="none" viewBox="0 0 24 24" stroke="currentColor">
                <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M20.354 15.354A9 9 0 018.646 3.646 9.003 9.003 0 0012 21a9.003 9.003 0 008.354-5.646z" />
              </svg>
            )}
          </button>
           {/* Example Nav Link - Use Link component */}
           {/*
           <Link to="/how-to-use" className="text-gray-700 dark:text-gray-300 hover:text-blue-600 dark:hover:text-blue-400 transition-colors duration-200">
             How to Use
           </Link>
           */}
        </div>
      </nav>

      {/* Header Section */}
      {/* Added pt-10 to push content down below the fixed/sticky nav if needed */}
      <header className="text-center mb-8 mt-10 px-4">
        <h1 className="text-4xl md:text-5xl font-bold text-blue-600 dark:text-blue-400 mb-4">
          Facebook Video Downloader
        </h1>
        <p className="text-xl md:text-2xl text-gray-700 dark:text-gray-300">
          Download your favorite Facebook videos easily and for free.
        </p>
      </header>

      {/* Main Download Section */}
      <main className="w-full max-w-xl bg-white dark:bg-gray-900 rounded-lg shadow-md dark:shadow-lg p-6 md:p-8 mx-4"> {/* Added mx-4 for horizontal padding on smaller screens */}
        <div className="mb-6">
          <label htmlFor="videoUrl" className="block text-lg font-medium text-gray-800 dark:text-gray-200 mb-2">
            Paste Facebook Video URL here:
          </label>
          <input
            type="text" // Changed type to text as URL type has built-in validation that might interfere
            id="videoUrl"
            className="w-full px-4 py-3 rounded-md border border-gray-300 dark:border-gray-600 bg-gray-50 dark:bg-gray-700 text-gray-900 dark:text-gray-100 placeholder-gray-500 dark:placeholder-gray-400 focus:outline-none focus:ring-2 focus:ring-blue-500 dark:focus:ring-blue-400 focus:border-blue-500 dark:focus:border-blue-400 transition-colors duration-300"
            placeholder="e.g., https://www.facebook.com/watch/?v=..."
            value={videoUrl}
            onChange={handleInputChange}
            disabled={isLoading} // Disable input while loading
          />
        </div>

        <button
          onClick={handleDownload}
          className="w-full bg-blue-600 hover:bg-blue-700 dark:bg-blue-700 dark:hover:bg-blue-600 text-white font-bold py-3 px-4 rounded-md focus:outline-none focus:ring-2 focus:ring-blue-500 focus:ring-opacity-50 transition-colors duration-300 disabled:opacity-50 disabled:cursor-not-allowed flex items-center justify-center"
          disabled={isLoading || !videoUrl.trim()} // Disable button if loading or input is empty
        >
          {isLoading ? (
             <>
               {/* Loading Spinner */}
               <svg className="animate-spin -ml-1 mr-3 h-5 w-5 text-white" xmlns="http://www.w3.org/2000/svg" fill="none" viewBox="0 0 24 24">
                 <circle className="opacity-25" cx="12" cy="12" r="10" stroke="currentColor" strokeWidth="4"></circle>
                 <path className="opacity-75" fill="currentColor" d="M4 12a8 8 0 018-8V0C5.373 0 0 5.373 0 12h4zm2 5.291A7.962 7.962 0 014 12H0c0 3.042 1.135 5.824 3 7.938l3-2.647z"></path>
               </svg>
               Processing...
             </>
           ) : (
             'Download Video'
           )}
        </button>

        {/* Error Display */}
        {error && (
          <div className="mt-4 p-3 bg-red-100 dark:bg-red-900 border border-red-400 dark:border-red-700 text-red-700 dark:text-red-300 rounded-md text-center">
            {error}
          </div>
        )}

        {/* Download Options Display */}
        {downloadOptions.length > 0 && (
          <div className="mt-6 border-t border-gray-200 dark:border-gray-700 pt-6">
            <h2 className="text-xl font-semibold text-gray-700 dark:text-gray-300 mb-4 text-center">Available Downloads:</h2>
            <div className="space-y-3">
              {downloadOptions.map((option, index) => (
                <a
                  key={index}
                  href={option.url} // In a real app, this URL would point to the actual video file
                  download // Suggests the browser should download the linked file
                  target="_blank" // Open in new tab, useful if direct download doesn't trigger
                  rel="noopener noreferrer"
                  className="block bg-green-500 hover:bg-green-600 dark:bg-green-600 dark:hover:bg-green-500 text-white font-medium py-3 px-4 rounded-md text-center no-underline transition duration-150 ease-in-out"
                >
                  Download {option.format} - {option.quality} {option.size ? `(${option.size})` : ''}
                </a>
              ))}
            </div>
             <p className="text-xs text-gray-500 dark:text-gray-400 mt-4 text-center">
               Tip: Right-click the button and choose "Save link as..." if the download doesn't start automatically.
             </p>
          </div>
        )}

        {/* Basic How-To / Disclaimer - Shown initially */}
         {!isLoading && !error && downloadOptions.length === 0 && (
             <div className="mt-6 text-center text-gray-500 dark:text-gray-400 text-sm">
                 <p>Enter the full URL of the Facebook video you want to download.</p>
                 <p className="mt-2 text-xs">Please ensure you have the necessary permissions to download the video. Downloads are intended for personal offline use only.</p>
             </div>
         )}

      </main>

      {/* Footer for Policy Links - Using placeholder Link component */}
      <footer className="text-center mt-8 text-gray-600 dark:text-gray-400 text-sm">
          {/* Replaced a tags with placeholder Link components */}
          <Link to="/privacy-policy" className="hover:underline mx-2">Privacy Policy</Link> |
          <Link to="/terms-of-service" className="hover:underline mx-2">Terms of Service</Link>
          <p className="mt-1">&copy; {new Date().getFullYear()} Your Site Name. All rights reserved.</p>
      </footer>
    </div>
  );
}

